from rich.repr import auto

class CustomEq:
    def __eq__(self, other):
        return True
    def __repr__(self):
        return "CustomEq()"

@auto
class Foo:
    def __init__(self, a=CustomEq()):
        self.a = a

foo = Foo()
print(f"Repr of foo: {repr(foo)}")
if repr(foo) == "Foo()":
    print("SUCCESS: Default value was skipped")
else:
    print(f"FAILURE: Default value was not skipped. Got: {repr(foo)}")

